import{_ as t,o as e,c as s,a4 as i}from"./chunks/framework.DzJZdBQK.js";const k=JSON.parse('{"title":"YARN命令","description":"","frontmatter":{"date":"2018-11-21T17:14:33","title":"YARN命令","categories":["frentend","nodejs"],"tags":["nodejs","yarn"]},"headers":[{"level":2,"title":"为什么","slug":"为什么","link":"#为什么","children":[]},{"level":2,"title":"安装","slug":"安装","link":"#安装","children":[]},{"level":2,"title":"更换安装源","slug":"更换安装源","link":"#更换安装源","children":[]},{"level":2,"title":"操作及对比","slug":"操作及对比","link":"#操作及对比","children":[]},{"level":2,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[{"level":3,"title":"yarn global","slug":"yarn-global","link":"#yarn-global","children":[]},{"level":3,"title":"指定bin目录","slug":"指定bin目录","link":"#指定bin目录","children":[]},{"level":3,"title":"指定registry但没有效果","slug":"指定registry但没有效果","link":"#指定registry但没有效果","children":[]}]},{"level":2,"title":"参考","slug":"参考","link":"#参考","children":[]}],"relativePath":"posts/frontend/nodejs/yarn.md","filePath":"posts/frontend/nodejs/yarn.md"}'),l={name:"posts/frontend/nodejs/yarn.md"};function n(r,a,d,h,o,p){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>自己用Hexo来做博客而用到了nodejs和npm。但npm生成的<code>node-modules</code>层次过深，时常打开文件夹时会很慢。</p><p>后来了解到了yarn，在yarn发布之前，所有Nodejs开发者用的都是npm包管理工具，而npm工具存在挺多难以忍受的诟病，包括安装速度慢、每次都要在线重新安装等问题，而yarn也是为了解决npm当前所存在的问题而出现的。</p><p>为了方便自己使用，整理了下安装和基本操作。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ul><li>如果原先有npm工具的话，安装yarn很简单，只需要一行命令即可：</li></ul><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarn</span></span></code></pre></div><ul><li>如果没有npm工具，安装yarn可参照<a href="https://yarnpkg.com/en/docs/install" target="_blank" rel="noreferrer">各平台下yarn工具安装方式</a>。</li></ul><h2 id="更换安装源" tabindex="-1">更换安装源 <a class="header-anchor" href="#更换安装源" aria-label="Permalink to &quot;更换安装源&quot;">​</a></h2><p>安装yarn之后默认的包安装源是<a href="https://registry.yarnpkg.com" target="_blank" rel="noreferrer">https://registry.yarnpkg.com</a>，可用查看命令</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span></span></code></pre></div><p>若想提高yarn安装的速度，可将包安装源修改为cnpm的安装源，执行以下命令即可</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://registry.npm.taobao.org</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yarn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disturl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://npm.taobao.org/dist</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --global</span></span></code></pre></div><h2 id="操作及对比" tabindex="-1">操作及对比 <a class="header-anchor" href="#操作及对比" aria-label="Permalink to &quot;操作及对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>npm</th><th>yarn</th></tr></thead><tbody><tr><td>初始化项目</td><td>npm init</td><td>yarn init</td></tr><tr><td>安装依赖操作</td><td>npm install/link</td><td>yarn install/link</td></tr><tr><td>安装某个依赖，并且默认保存到package</td><td>npm install xxx —save</td><td>yarn add xxx</td></tr><tr><td>移除某个依赖项目</td><td>npm uninstall xxx —save</td><td>yarn remove xxx</td></tr><tr><td>安装某个开发时依赖项目</td><td>npm install --save -dev xxx</td><td>yarn add xxx —dev</td></tr><tr><td>更新某个依赖项目</td><td>npm update --save xxx</td><td>yarn upgrade xxx</td></tr><tr><td>安装某个全局依赖项目</td><td>npm install -g xxx</td><td>yarn global add xxx</td></tr><tr><td>发布/登录/登出，一系列NPM Registry操作</td><td>npm publish/login/logout</td><td>yarn publish/login/logout</td></tr><tr><td>运行某个命令</td><td>npm run/test</td><td>yarn run/test</td></tr><tr><td>查看帮助</td><td>npm -h</td><td>yarn -h</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><h3 id="yarn-global" tabindex="-1">yarn global <a class="header-anchor" href="#yarn-global" aria-label="Permalink to &quot;yarn global&quot;">​</a></h3><p>yarn 的全局安装并不是加 -g 或者 --global 这样的参数，它使用 <a href="https://yarnpkg.com/en/docs/cli/global" target="_blank" rel="noreferrer">yarn global</a> 命令。用 yarn global --help 可以看到子命令列表</p><p>这些子命令的用法和非 global 的同名命令用法差不多。</p><h3 id="指定bin目录" tabindex="-1">指定bin目录 <a class="header-anchor" href="#指定bin目录" aria-label="Permalink to &quot;指定bin目录&quot;">​</a></h3><p>对于一些带 CLI 的模块，通过 yarn global add 可能会出问题，yarn global bin查看目录，并把该目录添加到Path中。</p><h3 id="指定registry但没有效果" tabindex="-1">指定registry但没有效果 <a class="header-anchor" href="#指定registry但没有效果" aria-label="Permalink to &quot;指定registry但没有效果&quot;">​</a></h3><ol><li>yarn.lock中包含的registry信息与设置的registry不同，删除yarn.lock重新生成即可。</li></ol><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://segmentfault.com/a/1190000007189426" target="_blank" rel="noreferrer">yarn —— Nodejs包新管理工具</a></p><p><a href="https://segmentfault.com/a/1190000008489881" target="_blank" rel="noreferrer">使用 yarn global 代替 npm -g</a></p><p><a href="https://github.com/yarnpkg/yarn/issues/4862" target="_blank" rel="noreferrer">&quot;yarn config set registry&quot; is not work · Issue #4862 · yarnpkg/yarn (github.com)</a></p>`,27)])])}const y=t(l,[["render",n]]);export{k as __pageData,y as default};
